import 'dart:async'; import 'dart:math'; import 'package:flutter/material.dart'; import 'package:shared_preferences/shared_preferences.dart'; import 'package:device_info_plus/device_info_plus.dart';
void main() async { WidgetsFlutterBinding.ensureInitialized(); runApp(AviraApp()); }
class AviraApp extends StatelessWidget { @override Widget build(BuildContext c) => MaterialApp(debugShowCheckedModeBanner: false, home: MainScreen()); }
class SessionManager { static Future<void> save(String id,String phone,String name) async { var p=await SharedPreferences.getInstance(); await p.setString('userId', id); await p.setString('phone', phone); await p.setString('name', name); await p.setBool('isLoggedIn', true); } static Future<Map?> get() async { var p=await SharedPreferences.getInstance(); if(!(p.getBool('isLoggedIn')??false)) return null; return {'userId':p.getString('userId'),'phone':p.getString('phone'),'name':p.getString('name')}; } static Future<void> logout() async { var p=await SharedPreferences.getInstance(); await p.clear(); } }
class DeviceManager { static Future<String> getId() async { try{ var d=DeviceInfoPlugin(); var a=await d.androidInfo; return a.id; }catch(e){ return 'dev_${Random().nextInt(99999)}'; } } }
class AdminSecure { static const String adminNum='8955116739'; static String otp=''; static String gen(){ otp=(100000+Random().nextInt(900000)).toString(); return otp; } static bool verify(String n,String o)=> n.trim()==adminNum && o==otp; static Future<void> sendSMS(BuildContext c) async { gen(); ScaffoldMessenger.of(c).showSnackBar(SnackBar(content: Text('OTP $otp sent to $adminNum'), backgroundColor: Colors.green)); } }
class AdminPay { static String phonePe='8955116739'; static String account='SBI 1234567890'; static double commission=10.0; }
class UserModel { String id,name,phone,acc,pe; bool isSeller; double pending,earned; String? deviceId,forceLogout; UserModel(this.id,this.name,this.phone,{this.isSeller=false,this.acc='',this.pe='',this.pending=0,this.earned=0,this.deviceId,this.forceLogout}); }
class Product { String id,name,price,cat,sellerId,sellerName; int stock; bool isApproved; Product(this.id,this.name,this.price,this.cat,this.sellerId,this.sellerName,{this.stock=10,this.isApproved=true}); }
class Order { String id,pName,price,date,custId,custName,sellerId,status,payMethod; double comm,payout; bool isPaid; Order(this.id,this.pName,this.price,this.date,this.custId,this.custName,this.sellerId,{this.status='Paid to Admin',this.payMethod='UPI',this.comm=0,this.payout=0,this.isPaid=false}); }
List<UserModel> USERS=[]; List<Product> PRODS=[ Product('1','Red Bridal Saree','999','Saree','admin','Avira Store',stock:20), Product('2','Designer Kurti','599','Kurti','admin','Avira Store',stock:15), Product('3','Lehenga Choli','1299','Lehenga','admin','Avira Store',stock:10), Product('4','Suit Set','799','Suits','admin','Avira Store',stock:12), Product('5','Banarasi Saree','1499','Saree','admin','Avira Store',stock:8), Product('6','Anarkali Kurti','699','Kurti','admin','Avira Store',stock:18), ]; List<Order> ORDERS=[]; String? L_ID; String? L_NAME;
class MainScreen extends StatefulWidget { @override _MainScreenState createState() => _MainScreenState(); }
class _MainScreenState extends State<MainScreen> { int idx=0; bool checking=true; Timer? t; @override void initState(){ super.initState(); check(); } Future<void> check() async { var s=await SessionManager.get(); if(s!=null){ L_ID=s['userId']; L_NAME=s['name']; String dev=await DeviceManager.getId(); var u=USERS.where((e)=>e.id==L_ID).toList(); if(u.isNotEmpty && u[0].forceLogout==dev){ await SessionManager.logout(); L_ID=null; L_NAME=null; } else { listen(dev); } } setState(()=>checking=false); } void listen(String myDev){ t=Timer.periodic(Duration(seconds:3), (timer){ var u=USERS.where((e)=>e.id==L_ID).toList(); if(u.isNotEmpty && u[0].forceLogout==myDev){ timer.cancel(); SessionManager.logout(); setState((){L_ID=null; L_NAME=null;}); } }); } @override Widget build(BuildContext c){ if(checking) return Scaffold(body: Center(child: CircularProgressIndicator())); return Scaffold(body: [HomeScreen(), SearchScreen(), CustomerPanel(), YouScreen(onChange: ()=>setState((){}))][idx], bottomNavigationBar: BottomNavigationBar(type: BottomNavigationBarType.fixed, selectedItemColor: Color(0xFF9F2089), unselectedItemColor: Colors.grey, currentIndex: idx, onTap: (v)=>setState(()=>idx=v), items: [BottomNavigationBarItem(icon: Icon(Icons.home), label: 'Home'), BottomNavigationBarItem(icon: Icon(Icons.search), label: 'Search'), BottomNavigationBarItem(icon: Icon(Icons.shopping_bag), label: 'Orders'), BottomNavigationBarItem(icon: Icon(Icons.person), label: 'You')])); } }
class HomeScreen extends StatefulWidget { @override _HomeScreenState createState() => _HomeScreenState(); }
class _HomeScreenState extends State<HomeScreen> { String cat='All'; Timer? lpTimer; int lpCount=0; bool isLP=false; void startLP(){ isLP=true; lpCount=0; lpTimer=Timer.periodic(Duration(seconds:1), (timer){ lpCount++; setState((){}); if(lpCount>=15){ timer.cancel(); isLP=false; lpCount=0; setState((){}); openAdmin(); } }); } void cancelLP(){ lpTimer?.cancel(); isLP=false; lpCount=0; setState((){}); } void openAdmin(){ String num='',otp='',gen=''; showDialog(context: context, builder: (ctx)=> StatefulBuilder(builder: (ctx2,setSt)=> AlertDialog(title: Text('Admin Secure'), content: Column(mainAxisSize: MainAxisSize.min, children:[ TextField(decoration: InputDecoration(labelText: 'Admin Number', border: OutlineInputBorder()), keyboardType: TextInputType.phone, onChanged:(v)=>num=v), if(gen.isNotEmpty)...[ SizedBox(height:10), TextField(decoration: InputDecoration(labelText: 'OTP from SMS', border: OutlineInputBorder()), keyboardType: TextInputType.number, onChanged:(v)=>otp=v), Text('Testing: $gen', style: TextStyle(fontSize:9)) ]]), actions:[ if(gen.isEmpty) ElevatedButton(onPressed:() async { if(num.trim()!=AdminSecure.adminNum) return; String o=AdminSecure.gen(); setSt(()=>gen=o); await AdminSecure.sendSMS(context); }, child: Text('Send OTP via SMS'), style: ElevatedButton.styleFrom(backgroundColor: Colors.red,foregroundColor: Colors.white)), if(gen.isNotEmpty) ElevatedButton(onPressed:(){ if(AdminSecure.verify(num,otp)){ Navigator.pop(ctx); L_ID='ADMIN'; L_NAME='Admin'; SessionManager.save('ADMIN', num, 'Admin'); Navigator.push(context, MaterialPageRoute(builder:(_)=> AdminPanel())); } }, child: Text('Verify')) ]))); } void buy(Product p){ if(L_ID==null){ ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('You me login karo'))); return; } if(p.stock<=0) return; setState(()=>p.stock--); double price=double.tryParse(p.price)??0; double comm=price*AdminPay.commission/100; ORDERS.add(Order(DateTime.now().millisecondsSinceEpoch.toString(), p.name, p.price, '${DateTime.now().day}-${DateTime.now().month}', L_ID!, L_NAME!, p.sellerId, comm:comm, payout:price-comm)); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Ordered'), backgroundColor: Colors.green)); } @override Widget build(BuildContext c){ var list=PRODS.where((p)=> cat=='All' || p.cat==cat).toList(); return Scaffold(appBar: AppBar(backgroundColor: Colors.white, elevation: 0, title: GestureDetector(onLongPressStart: (_)=>startLP(), onLongPressEnd: (_)=>cancelLP(), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children:[ Text('Avira Store', style: TextStyle(color: Color(0xFF9F2089),fontWeight: FontWeight.bold,fontSize:22)), if(isLP) Text('Admin ${15-lpCount}s HOLD', style: TextStyle(fontSize:10,color:Colors.red)) ]))), body: Column(children:[ Container(width: double.infinity, color: Color(0xFFE8F5E9), padding: EdgeInsets.all(8), child: Text('100% Secure Shopping - Trusted by Avira', style: TextStyle(fontSize:12,color:Colors.green[700],fontWeight: FontWeight.bold))), SingleChildScrollView(scrollDirection: Axis.horizontal, child: Row(children:['All','Saree','Kurti','Lehenga','Suits'].map((e)=> Padding(padding: EdgeInsets.only(left:8), child: ChoiceChip(label: Text(e), selected: cat==e, onSelected:(v)=>setState(()=>cat=e)))).toList())), Expanded(child: GridView.builder(padding: EdgeInsets.all(10), gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,childAspectRatio:0.68,crossAxisSpacing:10,mainAxisSpacing:10), itemCount:list.length, itemBuilder:(ctx,i){ var p=list[i]; return Container(decoration: BoxDecoration(color: Colors.white,borderRadius: BorderRadius.circular(12),boxShadow:[BoxShadow(color: Colors.black12,blurRadius:4)]), child: Column(children:[ Expanded(child: Container(color: Colors.grey[200], child: Center(child: Icon(Icons.image,size:40)))), Padding(padding: EdgeInsets.all(8), child: Column(children:[ Text(p.name,style: TextStyle(fontWeight: FontWeight.bold,fontSize:12)), Text('Rs.${p.price}',style: TextStyle(color: Colors.green[700])), SizedBox(height:6), SizedBox(width: double.infinity, child: ElevatedButton(onPressed: ()=>buy(p), child: Text('Buy Now',style: TextStyle(fontSize:11)), style: ElevatedButton.styleFrom(backgroundColor: Color(0xFF9F2089),foregroundColor: Colors.white))) ])) ])); })) ])); } }
