class _SearchScreenState extends State<SearchScreen> { String q=''; @override Widget build(BuildContext c){ var list=PRODS.where((p)=> p.name.toLowerCase().contains(q.toLowerCase())).toList(); return Scaffold(appBar: AppBar(title: Text('Search'),backgroundColor: Color(0xFF9F2089),foregroundColor: Colors.white), body: Column(children:[ Padding(padding: EdgeInsets.all(12), child: TextField(decoration: InputDecoration(hintText: 'Search...',prefixIcon: Icon(Icons.search),border: OutlineInputBorder(borderRadius: BorderRadius.circular(12))), onChanged:(v)=>setState(()=>q=v))), Expanded(child: ListView.builder(itemCount:list.length, itemBuilder:(ctx,i){ return Card(child: ListTile(title: Text(list[i].name), subtitle: Text('Rs.${list[i].price}'))); })) ])); } }
class CustomerPanel extends StatefulWidget { @override _CustomerPanelState createState() => _CustomerPanelState(); }
class _CustomerPanelState extends State<CustomerPanel> { String tab='Orders'; @override Widget build(BuildContext c){ var myOrders=ORDERS.where((o)=> o.custId==L_ID).toList(); return Scaffold(appBar: AppBar(title: Text('My Account'),backgroundColor: Color(0xFF9F2089),foregroundColor: Colors.white), body: Column(children:[ if(L_ID!=null) Card(color: Colors.purple[50], margin: EdgeInsets.all(12), child: ListTile(leading: CircleAvatar(child: Text(L_NAME!=null?L_NAME![0]:'U')), title: Text(L_NAME??'Guest'), subtitle: Text('Auto login ON - Single device - Dusre me kholo to logout'))), Row(children:[ Padding(padding: EdgeInsets.all(8), child: ChoiceChip(label: Text('Orders ${myOrders.length}'),selected: tab=='Orders',onSelected:(v)=>setState(()=>tab='Orders'))), ChoiceChip(label: Text('Wishlist'),selected: tab=='Wish',onSelected:(v)=>setState(()=>tab='Wish')), SizedBox(width:8), ChoiceChip(label: Text('Address'),selected: tab=='Addr',onSelected:(v)=>setState(()=>tab='Addr')) ]), if(tab=='Orders') Expanded(child: myOrders.isEmpty? Center(child: Column(mainAxisAlignment: MainAxisAlignment.center, children:[Icon(Icons.shopping_bag_outlined,size:60,color:Colors.grey[300]),Text('No Orders'),Text('Home se Buy karo',style: TextStyle(fontSize:11,color:Colors.grey))])) : ListView.builder(itemCount: myOrders.length, itemBuilder:(ctx,i){ var o=myOrders[i]; return Card(color: o.isPaid? Colors.green[50]: Colors.orange[50], child: ListTile(leading: Icon(o.isPaid? Icons.local_shipping: Icons.hourglass_top, color: o.isPaid? Colors.green: Colors.orange), title: Text('${o.pName} Rs.${o.price}'), subtitle: Text('${o.date} - ${o.isPaid?"Seller ko bhej diya - Out for Delivery":"Admin ke paas secure hai"}\nPay: ${o.payMethod}'), trailing: Text(o.isPaid?"Delivered":"Pending",style: TextStyle(fontSize:10,color:o.isPaid?Colors.green:Colors.orange)))); })), if(tab=='Wish') Expanded(child: Center(child: Text('Wishlist - Home se ❤️ karo'))), if(tab=='Addr') Expanded(child: ListView(children:[ ListTile(title: Text('Home Address'), subtitle: Text('Add karo checkout ke liye'), trailing: Icon(Icons.add_location)), Padding(padding: EdgeInsets.all(12), child: ElevatedButton(onPressed: (){}, child: Text('Add Address'), style: ElevatedButton.styleFrom(backgroundColor: Color(0xFF9F2089),foregroundColor: Colors.white))) ])), ])); } }
class YouScreen extends StatefulWidget { final VoidCallback onChange; YouScreen({required this.onChange}); @override _YouScreenState createState() => _YouScreenState(); }
class _YouScreenState extends State<YouScreen> { void login(bool seller) async { String name='',phone='',acc='',pe=''; showDialog(context: context, builder: (ctx)=> AlertDialog(title: Text(seller?'Seller':'Customer Login'), content: Column(mainAxisSize: MainAxisSize.min, children:[ TextField(decoration: InputDecoration(labelText: 'Name*',border: OutlineInputBorder()), onChanged:(v)=>name=v), SizedBox(height:8), TextField(decoration: InputDecoration(labelText: 'Phone* (Isi se ID khulegi)',border: OutlineInputBorder()), keyboardType: TextInputType.phone, onChanged:(v)=>phone=v), if(seller)...[ SizedBox(height:8), TextField(decoration: InputDecoration(labelText: 'Account*',border: OutlineInputBorder()), onChanged:(v)=>acc=v), SizedBox(height:8), TextField(decoration: InputDecoration(labelText: 'PhonePe*',border: OutlineInputBorder()), onChanged:(v)=>pe=v) ]]), actions:[ TextButton(onPressed:() async { if(name.isEmpty||phone.isEmpty) return; String id='U_$phone'; String devId=await DeviceManager.getId(); var ex=USERS.where((u)=>u.id==id).toList(); if(ex.isEmpty){ USERS.add(UserModel(id,name,phone,acc:acc,pe:pe,deviceId:devId,isSeller:seller)); } else { if(ex[0].deviceId!=devId) ex[0].forceLogout=ex[0].deviceId; ex[0].deviceId=devId; } await SessionManager.save(id, phone, name); L_ID=id; L_NAME=name; Navigator.pop(ctx); widget.onChange(); setState((){}); }, child: Text('Login')) ])); } void logout() async { await SessionManager.logout(); L_ID=null; L_NAME=null; widget.onChange(); setState((){}); } @override Widget build(BuildContext c) => Scaffold(appBar: AppBar(title: Text('You - Avira'),backgroundColor: Colors.white,foregroundColor: Colors.black,elevation:0), body: ListView(children:[ if(L_ID!=null) Card(color: Colors.green[50],margin: EdgeInsets.all(12), child: ListTile(leading: CircleAvatar(child: Text(L_NAME![0])), title: Text('$L_NAME'), subtitle: Text('ID: $L_ID\nAuto login till logout'), trailing: ElevatedButton(onPressed: logout, child: Text('Logout'), style: ElevatedButton.styleFrom(backgroundColor: Colors.red,foregroundColor: Colors.white)))), if(L_ID==null)...[ Card(child: ListTile(title: Text('Customer Login'), subtitle: Text('Phone se - Auto login'), trailing: Icon(Icons.arrow_forward_ios,size:16), onTap:()=>login(false))), Card(child: ListTile(title: Text('Seller Login'), subtitle: Text('Sell - Single device'), trailing: Icon(Icons.arrow_forward_ios,size:16), onTap:()=>login(true))), ], Padding(padding: EdgeInsets.all(12), child: Text('Tip: Avira Store ko 15 sec dabao Admin khulega OTP SMS me', textAlign: TextAlign.center, style: TextStyle(fontSize:10,color:Colors.grey))) ])); }
