class _AdminPanelState extends State<AdminPanel> { String tab='Orders'; @override Widget build(BuildContext c){ double sale=ORDERS.fold(0,(s,o)=> s+(double.tryParse(o.price)??0)); return Scaffold(appBar: AppBar(title: Text('ADMIN'),backgroundColor: Colors.red,foregroundColor: Colors.white), body: Column(children:[ Container(color: Colors.red[50],padding: EdgeInsets.all(10), child: Text('Sale Rs.$sale PhonePe: ${AdminPay.phonePe} - Only Admin sees')), SingleChildScrollView(scrollDirection: Axis.horizontal, child: Row(children:[ ChoiceChip(label: Text('Orders'),selected: tab=='Orders',onSelected:(v)=>setState(()=>tab='Orders')), ChoiceChip(label: Text('Users'),selected: tab=='Users',onSelected:(v)=>setState(()=>tab='Users')), ChoiceChip(label: Text('Products'),selected: tab=='Products',onSelected:(v)=>setState(()=>tab='Products')) ])), if(tab=='Orders') Expanded(child: ListView.builder(itemCount: ORDERS.length, itemBuilder:(ctx,i){ var o=ORDERS[i]; return Card(child: ListTile(title: Text('${o.pName} Rs.${o.price}'), subtitle: Text('${o.custName} Payout ${o.payout} ${o.isPaid?"Paid":"Pending"}'), trailing:!o.isPaid? ElevatedButton(onPressed:(){ setState(()=> o.isPaid=true); }, child: Text('Pay')): Icon(Icons.check,color:Colors.green))); })), if(tab=='Users') Expanded(child: ListView.builder(itemCount: USERS.length, itemBuilder:(ctx,i){ var u=USERS[i]; return Card(child: ListTile(title: Text('${u.name} ${u.isSeller?"SELLER":""}'), subtitle: Text('Phone ${u.phone} Device ${u.deviceId}'))); })), if(tab=='Products') Expanded(child: ListView.builder(itemCount: PRODS.length, itemBuilder:(ctx,i){ return Card(child: ListTile(title: Text(PRODS[i].name), subtitle: Text('Rs.${PRODS[i].price}'))); })) ])); } }
